#!/usr/bin/env ruby
# frozen_string_literal: true

# Tests for scripts/lib/yarn_lock_names.rb, against the Yarn Berry lockfile
# shapes the apps commit: scoped and unscoped npm packages, several ranges
# resolving to one entry, patch: resolutions, and the app's workspace entry.
# Run via:
#
#   ruby scripts/test/yarn_lock_names_test.rb

require "tmpdir"
require "open3"

LIB = File.expand_path("../lib/yarn_lock_names.rb", __dir__)

BERRY_LOCK = <<~LOCK
  # This file is generated by running "yarn install" inside your project.
  # Manual changes might be lost - proceed with caution!

  __metadata:
    version: 10
    cacheKey: 10c0

  "@esbuild/linux-x64@npm:0.28.2":
    version: 0.28.2
    resolution: "@esbuild/linux-x64@npm:0.28.2"
    conditions: os=linux & cpu=x64
    languageName: node
    linkType: hard

  "esbuild@npm:^0.28.0, esbuild@npm:^0.28.2":
    version: 0.28.2
    resolution: "esbuild@npm:0.28.2"
    languageName: node
    linkType: hard

  "resolve@patch:resolve@npm%3A^1.22.8#optional!builtin<compat/resolve>":
    version: 1.22.8
    resolution: "resolve@patch:resolve@npm%3A1.22.8#optional!builtin<compat/resolve>::version=1.22.8&hash=c3c19d"
    languageName: node
    linkType: hard

  "markaz@workspace:.":
    version: 0.0.0-use.local
    resolution: "markaz@workspace:."
    languageName: unknown
    linkType: soft
LOCK

CLASSIC_LOCK = <<~LOCK
  # yarn lockfile v1

  esbuild@^0.28.0:
    version "0.28.2"
    resolved "https://registry.yarnpkg.com/esbuild/-/esbuild-0.28.2.tgz"
LOCK

@failures = []

def assert_equal(expected, actual, label)
  if expected == actual
    puts "  PASS #{label}"
  else
    @failures << label
    puts "  FAIL #{label}"
    puts "    expected: #{expected.inspect}"
    puts "    actual:   #{actual.inspect}"
  end
end

Dir.mktmpdir do |dir|
  berry = File.join(dir, "berry.lock")
  classic = File.join(dir, "classic.lock")
  File.write(berry, BERRY_LOCK)
  File.write(classic, CLASSIC_LOCK)

  puts "lists each resolved package name once, sorted bytewise"
  stdout, stderr, status = Open3.capture3(RbConfig.ruby, LIB, berry)
  assert_equal(true, status.success?, "exits 0 (stderr: #{stderr})")
  assert_equal("@esbuild/linux-x64\nesbuild\nmarkaz\nresolve\n", stdout, "names")

  puts "refuses a lockfile with no resolution entries"
  stdout, _, status = Open3.capture3(RbConfig.ruby, LIB, classic)
  assert_equal(false, status.success?, "Yarn Classic lockfile exits non-zero")
  assert_equal("", stdout, "prints no names")
end

if @failures.empty?
  puts "\nAll yarn_lock_names tests passed."
else
  puts "\n#{@failures.length} failure(s): #{@failures.join(', ')}"
  exit 1
end
